// Exact quartic certificate: nuisance check.
#include "s61_binary_deeper_quartic_field_20261101.hpp"
void elim(Row&row,int p,const Row&b){auto it=row.find(p);if(it==row.end())return;Rat h=it->second;for(auto&[j,v]:b){Rat z=sub(row[j],mul(h,v));if(z.zero())row.erase(j);else row[j]=std::move(z);}}
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);flint_set_num_threads(2);{ifstream bin(argv[1]),qin(argv[2]);int nr,nc;bin>>nr>>nc;assert(nr==389&&nc==495);vector<Row>B(nr);vector<int>pivs(nr);for(int i=0;i<nr;i++){int n;bin>>pivs[i]>>n;for(int j=0;j<n;j++){int k;bin>>k;Rat c;readpoly(bin,c.n);readpoly(bin,c.d);c.reduce();B[i].emplace(k,std::move(c));}}cerr<<"BASIS LOADED\n";
map<vector<int>,int>ix;int index=0;for(int a=0;a<9;a++)for(int b=a;b<9;b++)for(int c=b;c<9;c++)for(int d=c;d<9;d++){vector<int>m(9);m[a]++;m[b]++;m[c]++;m[d]++;ix[m]=index++;}int cases;qin>>cases;int limit=argc>4?stoi(argv[4]):cases;ofstream out(argv[3]);assert(out);out<<limit<<'\n';for(int z=0;z<limit;z++){int id;long n;qin>>id>>n;assert(qin);map<int,Row>R;fmpq_t c;fmpq_init(c);ulong ex[2];for(long j=0;j<n;j++){string v;qin>>v>>ex[0]>>ex[1];assert(fmpq_set_str(c,v.c_str(),10)==0);fmpq_canonicalise(c);int outer=0,pow=1;for(int k=0;k<5;k++){int a;qin>>a;assert(a<=1);outer+=a*pow;pow*=3;}assert(outer==0||outer==3||outer==27||outer==81);vector<int>mon(9);for(int&x:mon)qin>>x;assert(ix.count(mon));fmpq_mpoly_push_term_fmpq_ui(R[outer][ix[mon]].n,c,ex,ctx);}long nd;qin>>nd;Rat denominator;for(long j=0;j<nd;j++){string v;qin>>v>>ex[0]>>ex[1];assert(fmpq_set_str(c,v.c_str(),10)==0);fmpq_canonicalise(c);for(int k=0;k<14;k++){int a;qin>>a;assert(a==0);}fmpq_mpoly_push_term_fmpq_ui(denominator.n,c,ex,ctx);}fmpq_mpoly_sort_terms(denominator.n,ctx);fmpq_mpoly_combine_like_terms(denominator.n,ctx);
for(auto&[outer,row]:R){if(outer==0)continue;for(auto&[j,v]:row){fmpq_mpoly_sort_terms(v.n,ctx);fmpq_mpoly_combine_like_terms(v.n,ctx);fmpq_mpoly_set(v.d,denominator.n,ctx);v.reduce();}cerr<<"REDUCE "<<id<<" OUTER "<<outer<<" ROWSIZE "<<row.size()<<'\n';for(int i=0;i<nr;i++)elim(row,pivs[i],B[i]);cerr<<"RESULT "<<id<<" OUTER "<<outer<<" ROWSIZE "<<row.size()<<'\n';if(outer!=0)assert(row.empty());else{out<<id<<' '<<row.size()<<'\n';for(auto&[j,v]:row){out<<j<<'\n';writepoly(out,v.n);writepoly(out,v.d);}out.flush();}}fmpq_clear(c);}
}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
